"""Score frozen H1/H2 candidates with cases created after the model hosts stop."""
from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor
from hashlib import sha256
import json
from pathlib import Path
import re
import secrets
import sys

from base_assess import assess, architecture
from hard_assess import heldout_cases

ROOT = Path(__file__).resolve().parent
MODES = ('standard', 'standard-checklist', 'building-loop')
SOURCES = ('entry.py', 'events.py', 'ledger.py', 'windows.py')
STAGES = {'g1': 'H1', 'g2': 'H2'}


def digest(data):
    return sha256(data).hexdigest()


def read_json(path):
    return json.loads(path.read_text(encoding='utf-8-sig'))


def score(task):
    run, mode, stage, recorded, seed = task
    location = run / 'frozen' / mode / stage
    files = [{"path": name, "sha256": digest((location / name).read_bytes()) if (location / name).is_file() else None}
             for name in SOURCES]
    assert recorded['after'] == files, (run.name, mode, stage)
    cases = heldout_cases(stage, seed, 24)
    # Fixed checks are already in the online suite. These freshly sampled
    # reservations, time windows and replay chains were never inputs to that suite.
    cases = {name: value for name, value in cases.items() if name.startswith('generated-')}
    assert len(cases) >= 16
    outcomes = assess(location, cases, mask_exceptions=True)
    for row in outcomes:
        row['id'] = digest(f"{seed}/{row['id']}".encode())[:20]
    return {"run": run.name, "mode": mode, "stage": STAGES[stage], "carry": recorded['carry'],
            "phase": recorded.get('nativePhase'), "terminal": recorded['terminal'], "artifacts": files,
            "passed": sum(row['status'] == 'passed' for row in outcomes), "total": len(outcomes),
            "architecture": architecture(location), "cases": outcomes}


def main():
    args = sys.argv[1:]
    if not args or not all(re.fullmatch(r'r-[A-Za-z0-9]+', name) for name in args):
        raise ValueError('Specify only exact isolated run IDs')
    confirmed = read_json(ROOT / 'reservation-process-cleanup.json')
    assert set(confirmed['runIds']) == set(args) and not confirmed['remainingOwnedProcesses']
    tasks = []
    missing = []
    for name in args:
        run = ROOT / name
        meta = read_json(run / 'metadata.json')
        assert meta['isolatedHostStopped'] and meta['formalProfileFingerprintsUnchanged']
        for mode in MODES:
            for stage in STAGES:
                evidence = run / f'{mode}-{stage}.json'
                if evidence.is_file():
                    tasks.append((run, mode, stage, read_json(evidence)))
                else:
                    missing.append({"run": name, "mode": mode, "stage": STAGES[stage]})
    seed_file = ROOT.parent / 'private-grader/reservation-postfreeze.seed'
    try:
        with seed_file.open('x', encoding='ascii') as fp:
            fp.write(secrets.token_hex(16) + '\n')
    except FileExistsError:
        # Preserve one exact set of post-freeze inputs on a retry of the grader.
        pass
    seed = seed_file.read_text(encoding='ascii').strip()
    assert re.fullmatch('[0-9a-f]{32}', seed)
    assert digest(seed.encode()) not in {read_json(ROOT / name / 'metadata.json')['seedSha256'] for name in args}
    with ThreadPoolExecutor(max_workers=3) as executor:
        rows = list(executor.map(score, [(*item, seed) for item in tasks]))
    result = {"spec": "building-loop-frozen-hard-postflight/1", "seedSha256": digest(seed.encode()),
              "generatorSha256": digest((ROOT / 'hard_assess.py').read_bytes()),
              "proofOfHostExit": confirmed, "missingFrozenCandidates": missing, "stages": rows}
    (ROOT / 'postfreeze-results.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8', newline='\n')
    for row in rows:
        print(row['run'], row['mode'], row['stage'], f"{row['passed']}/{row['total']}")


if __name__ == '__main__':
    main()

