launch-reservation.ps1.text:
param(
    [Parameter(Mandatory)][string]$Archive,
    [Parameter(Mandatory)][string]$Sha256,
    [ValidatePattern('^[A-Za-z0-9-]+$')][string]$Label = 'reservation',
    [int[]]$Repetitions = @(1, 2),
    [switch]$Preflight
)
$ErrorActionPreference = 'Stop'
$runnerRoot = $PSScriptRoot
$qaRoot = Split-Path -Parent $runnerRoot
$qaTemp = Join-Path $qaRoot 'launcher-tmp'
$graderDirectory = Join-Path $qaRoot 'private-grader'
$onlineSeed = Join-Path $graderDirectory 'reservation-online.seed'
$archivePath = (Resolve-Path -LiteralPath $Archive).Path
$packageDirectory = (Join-Path $qaRoot 'package') + [IO.Path]::DirectorySeparatorChar
if (-not $archivePath.StartsWith($packageDirectory, [StringComparison]::OrdinalIgnoreCase)) {
    throw 'Expected the exact candidate archive inside the G drive QA package directory'
}
$Sha256 = $Sha256.ToLowerInvariant()
if ($Sha256 -notmatch '^[0-9a-f]{64}$' -or (Get-FileHash -LiteralPath $archivePath).Hash -ne $Sha256) {
    throw 'The candidate archive digest does not match'
}
if (-not (Test-Path Env:DEEPSEEK_API_KEY)) {
    throw 'The isolated Windows DSH runner needs its configured DeepSeek credential'
}
New-Item -ItemType Directory -Path $qaTemp,$graderDirectory -Force | Out-Null
if (-not (Test-Path -LiteralPath $onlineSeed)) {
    $seedText = [Convert]::ToHexString([Security.Cryptography.RandomNumberGenerator]::GetBytes(16)).ToLowerInvariant()
    $seedFile = [IO.File]::Open($onlineSeed, [IO.FileMode]::CreateNew)
    try { $seedFile.Write([Text.Encoding]::ASCII.GetBytes($seedText + "`n")) }
    finally { $seedFile.Dispose() }
}
$env:TEMP = $qaTemp
$env:TMP = $qaTemp
$jobs = foreach ($rep in $Repetitions) {
    $stdout = Join-Path $runnerRoot "$Label-$rep.stdout"
    $stderr = Join-Path $runnerRoot "$Label-$rep.stderr"
    if ((Test-Path -LiteralPath $stdout) -or (Test-Path -LiteralPath $stderr)) {
        throw "Existing launch record for repetition $rep"
    }
    $nodeArguments = @('run.mjs', $archivePath, $Sha256, "$rep", '300000', '600000', $onlineSeed)
    if ($Preflight) { $nodeArguments += '--preflight' }
    $job = Start-Process -FilePath (Get-Command node).Source -WorkingDirectory $runnerRoot -WindowStyle Hidden -PassThru `
        -ArgumentList $nodeArguments -RedirectStandardOutput $stdout -RedirectStandardError $stderr
    [pscustomobject]@{ rep = $rep; pid = $job.Id; stdout = $stdout; stderr = $stderr }
}
$jobs | ConvertTo-Json -Depth 3

