"""Independently reconcile exact frozen source locations with actual subprocess traces."""
from __future__ import annotations

import ast
from hashlib import sha256
import json
from pathlib import Path
import re
import subprocess
import sys

from base_assess import PATHS, json_equal
from hard_assess import apply_cases, base_cases, revision_cases


ROOT = Path(__file__).resolve().parent
MODES = ("standard", "standard-checklist", "building-loop")
STAGES = {"g1": "H1", "g2": "H2"}


def read(path):
    return json.loads(path.read_bytes())


def stdout_trace(source, incoming):
    argv = [sys.executable, "-B", str(ROOT / "review-probe.py"), str(source),
            str(ROOT / "python_syntax.py"), str(ROOT / "python_trace.py"), "entry.py", *PATHS]
    raw = incoming if isinstance(incoming, str) else json.dumps(incoming)
    probe = subprocess.run(argv, input=json.dumps({"target": None, "trace": True, "stdin": raw}),
                           text=True, capture_output=True, timeout=8, check=False)
    if probe.returncode != 0:
        return {"exitCode": probe.returncode, "runnerStatus": "unavailable", "executed": []}
    try:
        reply = json.loads(probe.stdout)
        response = json.loads(reply["stdout"])
    except (ValueError, KeyError):
        return {"runnerStatus": "unavailable", "executed": []}
    return {"exitCode": reply.get("exitCode"), "response": response,
            "executed": reply.get("executed", []), "runnerStatus": "observed"}


def literal(node, expected):
    return isinstance(node, ast.Constant) and type(node.value) is type(expected) and node.value == expected


def names(nodes):
    return [node.id for node in nodes if isinstance(node, ast.Name)]


def guarded_nonobject(test, parameter):
    """Recognize a negative dict guard or the else branch of a positive dict guard."""
    if isinstance(test, ast.UnaryOp) and isinstance(test.op, ast.Not):
        return guarded_nonobject(test.operand, parameter) == "else" and "body"
    if isinstance(test, ast.Call) and isinstance(test.func, ast.Name) and test.func.id == "isinstance":
        if names(test.args) == [parameter, "dict"]:
            return "else"
    if isinstance(test, ast.Compare) and isinstance(test.left, ast.Call) and len(test.ops) == 1:
        test_call = test.left
        if isinstance(test_call.func, ast.Name) and test_call.func.id == "type" and names(test_call.args) == [parameter]:
            if names(test.comparators) == ["dict"]:
                return "body" if isinstance(test.ops[0], (ast.IsNot, ast.NotEq)) else (
                    "else" if isinstance(test.ops[0], (ast.Is, ast.Eq)) else None)
    if isinstance(test, ast.BoolOp) and isinstance(test.op, ast.Or):
        if any(guarded_nonobject(term, parameter) == "body" for term in test.values):
            return "body"
    return None


def contains_error(node, code):
    return any(literal(part, code) for part in ast.walk(node))


def direct_statements(tree):
    """Give each statement to its nearest function while preserving transport handlers."""
    def visit(node, routine=None, under_handler=False):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            routine = node
        under_handler = under_handler or isinstance(node, ast.ExceptHandler)
        yield node, routine, under_handler
        for child in ast.iter_child_nodes(node):
            yield from visit(child, routine, under_handler)
    return list(visit(tree))


def executed_location(file, node, executed):
    return (file, node.lineno) in executed


def hints(source, executed, code, role):
    """Extract concrete locations. Absence of support remains unresolved."""
    locations = []
    for file in PATHS:
        path = source / file
        if not path.is_file():
            continue
        try:
            tree = ast.parse(path.read_bytes(), filename=file)
        except SyntaxError:
            continue
        for node, routine, handler in direct_statements(tree):
            if not hasattr(node, "lineno") or not executed_location(file, node, executed):
                continue
            decisions = []
            if role == "transport-fallback" and isinstance(node, ast.ExceptHandler):
                decisions = [statement for statement in node.body if contains_error(statement, code)]
            elif role == "business-nonobject" and routine and isinstance(node, ast.If) and not handler:
                positional = [*routine.args.posonlyargs, *routine.args.args]
                if positional:
                    side = guarded_nonobject(node.test, positional[0].arg)
                    decisions = [statement for statement in getattr(node, side, []) if contains_error(statement, code)] if side else []
            elif role == "scoped-business" and not handler and isinstance(node, (ast.Return, ast.Raise)):
                if contains_error(node, code):
                    decisions = [node]
            for decision in decisions:
                if decision.lineno != node.lineno or role == "scoped-business":
                    if executed_location(file, decision, executed):
                        locations.append({"file": file, "line": decision.lineno, "symbol": routine.name if routine else "<module>"})
    return locations


def control_rows(source, stage):
    base = base_cases()
    apply = apply_cases()
    revision = revision_cases()
    controls = [
        ("business-nonobject", "ledger.py", base["business-nonobject-array"]),
        ("transport-fallback", "entry.py", base["transport-malformed-json"]),
        ("scoped-business", "events.py", apply["apply-conflicting-identity"]),
        ("scoped-business", "ledger.py", apply["apply-release-absent"]),
    ]
    if stage == "g2":
        controls += [("scoped-business", "windows.py", revision["revision-reserve-checks-window"]),
                     ("scoped-business", "ledger.py", revision["revision-conflict-beats-window"])]
    results = []
    for role, owner, (incoming, expected) in controls:
        actual = stdout_trace(source, incoming)
        result_matches = actual.get("exitCode") == 0 and json_equal(actual.get("response"), expected)
        lines = {(row["path"], row["line"]) for row in actual["executed"]}
        positions = hints(source, lines, expected["error"], role)
        status = "behavior-failed" if not result_matches else "unresolved"
        if result_matches and len(positions) == 1:
            status = "confirmed" if positions[0]["file"] == owner else "wrong-module"
        results.append({"check": role, "expectedOwner": owner, "expectedCode": expected["error"],
                        "status": status, "decisionLocations": positions, "actual": actual})
    good_input, good_expected = base["inspect-empty"]
    good_actual = stdout_trace(source, good_input)
    trace_files = {row["path"] for row in good_actual["executed"]}
    results.append({"check": "forwarding-control", "status": "path-and-result-observed"
                    if good_actual.get("exitCode") == 0 and json_equal(good_actual.get("response"), good_expected)
                    and {"entry.py", "ledger.py"} <= trace_files else "unresolved", "actual": good_actual})
    return results


def generated_proof(source, recorded):
    proof = recorded.get("responsibilityProof")
    if not proof:
        return {"status": "missing"}
    file = source / "modules/architecture.md"
    if not file.is_file():
        return {"status": "missing-architecture"}
    lines = file.read_text(encoding="utf-8").splitlines()
    try:
        heading = lines.index("## 模块职责")
        begin = lines.index("```text", heading + 1)
        end = lines.index("```", begin + 1)
        rendered = {row["id"]: row for row in (json.loads(line) for line in lines[begin + 1:end])}
    except (ValueError, KeyError):
        return {"status": "invalid-generated-section"}
    rows = [{"id": row["id"], "status": row.get("status"), "matches": (
        row.get("status") == "passed" and row.get("traceSha256") and
        rendered.get(row["id"], {}).get("traceSha256") == row["traceSha256"] and
        rendered[row["id"]].get("decision") == row.get("actual") and
        rendered[row["id"]].get("clause") == row.get("clause") and
        rendered[row["id"]].get("response") == row.get("response"))} for row in proof["rows"]]
    actual = {row["id"] for row in rows if row["matches"]}
    expected = {"business-nonobject", "entry-json-fallback", "entry-forwarding"}
    return {"status": "matched" if actual == expected == set(rendered) else "mismatch", "rows": rows}


def main():
    runs = sys.argv[1:]
    if not runs or not all(re.fullmatch(r"r-[A-Za-z0-9]+", name) for name in runs):
        raise SystemExit("Pass exact stopped isolated run IDs")
    out = []
    for name in runs:
        directory = ROOT / name
        metadata = read(directory / "metadata.json")
        assert metadata["isolatedHostStopped"] and metadata["formalProfileFingerprintsUnchanged"]
        for mode in MODES:
            for stage, label in STAGES.items():
                report = directory / f"{mode}-{stage}.json"
                if not report.is_file():
                    continue
                source = directory / "frozen" / mode / stage
                recorded = read(report)
                pins = [{"path": file, "sha256": sha256((source / file).read_bytes()).hexdigest()
                         if (source / file).is_file() else None} for file in PATHS]
                assert pins == recorded["after"]
                out.append({"run": name, "mode": mode, "stage": label,
                            "sourcePins": pins, "controls": control_rows(source, stage),
                            **({"generatedProof": generated_proof(source, recorded)} if mode == "building-loop" else {})})
    (ROOT / "reservation-responsibility-public.json").write_text(
        json.dumps({"scope": "independent source-located responsibility controls; unresolved when static proof unavailable",
                    "runs": out}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

