import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { digest, files } from './fixture.mjs';

const root = dirname(fileURLToPath(import.meta.url));
const [runId, archiveLabel] = process.argv.slice(2);
assert.match(runId ?? '', /^r-[A-Za-z0-9]+$/u);
assert.match(archiveLabel ?? '', /^[a-z0-9-]+$/u);
const read = path => readFileSync(path);
const data = path => JSON.parse(read(path));
const location = join(root, runId);
const metadata = data(join(location, 'metadata.json'));
const packageFolder = resolve(root, '../package');
const manifest = data(join(packageFolder, 'runtime-manifest-' + archiveLabel + '.json'));
assert.equal(metadata.archiveSha256, manifest.archiveSha256);
assert.equal(digest(read(join(packageFolder, 'dsh-building-loop-0.7.29-' + archiveLabel + '.tgz'))), manifest.archiveSha256);
assert.ok(metadata.preflight && metadata.isolatedHostStopped && metadata.formalProfileFingerprintsUnchanged);
const installed = join(location, 'h', 'profiles', 'qa', 'node_modules', 'dsh-building-loop');
for (const [name, sha256] of Object.entries(manifest.files)) assert.equal(digest(read(join(installed, name))), sha256, name);

const tool = name => import(pathToFileURL(join(installed, 'governance', name)));
const { architectureResponsibilityResult, parseArchitectureResponsibilities } = await tool('architecture-responsibilities.mjs');
const { inputContractCases, parseInputContracts } = await tool('input-contracts.mjs');
const { units } = await import(pathToFileURL(join(location, 'h', 'profiles', 'qa', 'witness.mjs')));
const examples = data(join(root, 'public-input-examples.json'));
const fakeInventory = { base: ['test'], carry: ['test'], g1: ['test'], g2: ['test'] };
const policy = units('not-used-by-the-replay', fakeInventory, 'not-used-by-the-replay', examples, pathToFileURL(join(root, '/'))).K01;
const diagnostics = policy.codeTask.diagnostics;
const parsed = parseInputContracts(diagnostics.inputContracts, diagnostics.reviewRecipes, diagnostics.syntaxRecipe);
const cases = new Map(inputContractCases(parsed).map(row => [row.id, row]));
const claims = parseArchitectureResponsibilities(policy.architecture.responsibilities, files, { ...diagnostics, inputContracts: parsed });
const calibration = data(join(root, 'calibration-public.json'));
const map = { business: 'business', fallback: 'fallback', forwarding: 'forward' };
const response = (claim, traceKey) => {
  const trace = calibration.traceControls[traceKey];
  const registered = cases.get(claim.exampleId);
  assert.equal(trace.stdinSha256, digest(registered.input.stdin));
  return { id: claim.exampleId, status: 'passed', executed: trace.executed,
    responseMatches: JSON.stringify(trace.stdout) === JSON.stringify(registered.expected.json) };
};

function replay(folder, rowClaims, observed) {
  const sourceRoot = join(root, 'calibration', folder);
  const architecture = { ...policy.architecture, responsibilities: rowClaims };
  const artifacts = files.map(path => ({ path, sha256: digest(read(join(sourceRoot, path))) }));
  const frame = { root: sourceRoot };
  writeFileSync(join(sourceRoot, 'SPEC.md'), read(join(root, 'SPEC.md')));
  return architectureResponsibilityResult(frame, { ...policy, architecture }, { artifacts }, observed);
}

const observations = claims.map(claim => response(claim, map[claim.mode]));
assert.ok(observations.every(row => row.responseMatches));
const positive = replay('reference', claims, observations);
assert.deepEqual(positive.map(row => row.status), ['passed', 'passed', 'passed']);
const business = claims.find(row => row.mode === 'business');
const wrong = response(business, 'misplacedBusiness');
assert.equal(wrong.responseMatches, true);
const negative = replay('wrong-owner', [business], [wrong]);
assert.deepEqual(negative.map(row => [row.status, row.actual.file]), [['mismatch', 'entry.py']]);
const proof = { spec: 'reservation-owner-runtime-replay/1', run: runId,
  archiveSha256: manifest.archiveSha256, installedRuntimeFiles: Object.keys(manifest.files).length, modelCalls: 0,
  controls: { registered: positive, sameOutputWrongOwner: negative } };
writeFileSync(join(root, archiveLabel === 'r72-final' ? 'host-replay-final-public.json' : 'host-replay-public.json'), JSON.stringify(proof, null, 2) + '\n');

