import assert from 'node:assert/strict';

// An observed end is independent of the 300/600 s samples. A pending trusted
// assessment can still unblock the workflow and therefore postpones idle-stall.
const STABLE_IDLE_MS = 2_000;
const INACTIVE_WITHOUT_TERMINAL_MS = 30_000;
const finished = new Set(['closed', 'retired']);

export function decideCompletion({ elapsedMs, phase, rootEnded, allIdle, quietMs, assessmentPending, building, operatorStop }) {
  if (operatorStop) return { terminal: 'operator-censored', classification: 'administrative' };
  if (!allIdle || quietMs < STABLE_IDLE_MS) return;
  if (building && finished.has(phase)) return { terminal: phase, classification: 'native-workflow-end' };
  if (!building && rootEnded) return { terminal: rootEnded, classification: 'native-response-end' };
  if (assessmentPending || quietMs < INACTIVE_WITHOUT_TERMINAL_MS || elapsedMs < INACTIVE_WITHOUT_TERMINAL_MS) return;
  if (building && phase === 'blocked') return { terminal: 'blocked', classification: 'native-blocked-and-idle' };
  if (building || !rootEnded) return { terminal: 'stalled-idle', classification: 'nonterminal-without-runnable-work' };
}

export function timeWindow(elapsedMs, capMs, frozenMs) {
  if (frozenMs !== undefined && elapsedMs >= frozenMs) return 'cleanup';
  return elapsedMs < capMs ? 'comparison' : 'extension';
}

// Called by no-model native preflight too, so the exact installed witness
// proves the 600 s and closure-tail cases before paid runs.
export function verifyCompletionPolicy() {
  const baseline = { elapsedMs: 700_000, phase: 'intake', allIdle: true, quietMs: 70_000,
    assessmentPending: false, building: true, operatorStop: false };
  const control = (changes, expected) => assert.equal(decideCompletion({ ...baseline, ...changes })?.terminal, expected);
  control({ elapsedMs: 1_300_000, allIdle: false }, undefined);
  control({ elapsedMs: 600_000, allIdle: false }, undefined);
  control({ phase: 'blocked', allIdle: false }, undefined);
  control({ assessmentPending: true }, undefined);
  control({ phase: 'intake', quietMs: 29_999 }, undefined);
  control({ phase: 'intake' }, 'stalled-idle');
  control({ phase: 'blocked' }, 'blocked');
  control({ phase: 'closed', elapsedMs: 600_000, quietMs: 327 }, undefined);
  control({ phase: 'closed', elapsedMs: 602_000, quietMs: 2_001 }, 'closed');
  control({ phase: 'closed', allIdle: false }, undefined);
  control({ building: false, rootEnded: 'completed', elapsedMs: 850_000 }, 'completed');
  control({ building: false, rootEnded: 'error', elapsedMs: 850_000 }, 'error');
  control({ allIdle: false, operatorStop: true }, 'operator-censored');
  assert.equal(timeWindow(750_000, 300_000), 'extension');
  assert.equal(timeWindow(750_000, 300_000, 750_000), 'cleanup');
  return { passed: 15, total: 15 };
}

