"""Validate immutable reservation records and batch event identities at the input boundary."""

import json

MAX_VALUE = 1_000_000_000
MAX_EVENTS = 4096
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
RELEASE_FIELDS = {"event_id", "kind", "id"}


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def signature(event):
    # Key order in the decoded mapping carries no meaning, so identity is the
    # canonical (sorted-key) encoding of the whole event object.
    return json.dumps(event, sort_keys=True, separators=(",", ":"))


def valid_event(event):
    if not isinstance(event, dict):
        return False
    kind = event.get("kind")
    if kind == "reserve":
        return (event.keys() == RESERVE_FIELDS
                and name(event["event_id"]) and name(event["id"])
                and name(event["resource"]) and name(event["owner"])
                and integer(event["start"]) and integer(event["end"])
                and event["start"] < event["end"])
    if kind == "release":
        return event.keys() == RELEASE_FIELDS and name(event["event_id"]) and name(event["id"])
    return False


def read_events(value):
    """Check every event's shape, then its identity, in input order."""
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
        return None, "invalid-event"
    for event in value:
        if not valid_event(event):
            return None, "invalid-event"
    seen = {}
    identities = []
    for event in value:
        # A different key order still names the same event object.
        key = signature(event)
        event_id = event["event_id"]
        prior = seen.get(event_id)
        if prior is not None and prior != key:
            return None, "conflicting-event"
        seen[event_id] = key
        identities.append(prior is not None)
    return identities, None

