    previous_resource, previous_end = None, None
    for row in ordered_rows:
        if row["resource"] == previous_resource and row["start"] < previous_end:
            return "overlap"
        previous_resource, previous_end = row["resource"], row["end"]
    return None


class Schedule:
    """Per-resource interval index over left-closed, right-open reservation spans.

    Each resource keeps its spans sorted by start with the furthest ``end`` of
    every prefix cached, so a conflict check, insert or removal costs
    ``O(log n)`` per resource instead of rescanning the whole book.
    """

    def __init__(self):
        self._resources = {}

    @classmethod
    def from_rows(cls, rows):
        schedule = cls()
        for row in rows:
            schedule._resource(row["resource"]).insert(row["start"], row["end"], row["id"])
        return schedule

    def _resource(self, resource):
        band = self._resources.get(resource)
        if band is None:
            band = self._resources[resource] = _Band()
        return band

    def conflicts(self, resource, start, end):
        band = self._resources.get(resource)
        return band is not None and band.conflicts(start, end)

    def add(self, resource, start, end, reservation_id):
        self._resource(resource).insert(start, end, reservation_id)

    def remove(self, resource, start, end, reservation_id):
        self._resources[resource].remove(start, end, reservation_id)


class _Band:
    """Ordered spans ``[start, end)`` for one resource with prefix maxima of ``end``."""

    __slots__ = ("starts", "ends", "ids", "peak")

    def __init__(self):
        self.starts = []
        self.ends = []
        self.ids = []
        self.peak = []

    def conflicts(self, start, end):
        # A stored span ``[s, e)`` overlaps ``[start, end)`` iff ``s < end`` and
        # ``start < e``. Spans are sorted by ``s``, so the ones with ``s < end``
        # form a prefix (``bisect_left``, since ``s == end`` merely touches);
        # inside that prefix a conflict exists iff some ``e > start``, which the
        # prefix maxima answer in one more bisect.
        limit = bisect_left(self.starts, end)
        return bisect_right(self.peak, start, 0, limit) != limit

    def insert(self, start, end, reservation_id):
        index = bisect_right(self.starts, start)
        self.starts.insert(index, start)
        self.ends.insert(index, end)
        self.ids.insert(index, reservation_id)
        if index == 0:
            top = end
        else:
            top = max(self.peak[index - 1], end)
        self.peak.insert(index, top)
