                and name(event["event_id"]) and name(event["id"])
                and name(event["resource"]) and name(event["owner"])
                and integer(event["start"]) and integer(event["end"])
                and event["start"] < event["end"])
    if kind == "release":
        return event.keys() == RELEASE_FIELDS and name(event["event_id"]) and name(event["id"])
    if kind == "transfer":
        # ``if_revision`` follows exactly the old revision rule; whether it still
        # matches the book is ledger business, not identity.
        return (event.keys() == TRANSFER_FIELDS
                and name(event["event_id"]) and name(event["id"])
                and name(event["resource"]) and name(event["owner"])
                and integer(event["start"]) and integer(event["end"])
                and event["start"] < event["end"]
                and integer(event["if_revision"], 1))
    return False


def read_events(value):
    """Check every event's shape, then its identity, in input order."""
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
