from windows import Schedule, Windows, first_overlap, read_closed


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def inspect(request):
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def reserve(event):
    # A reservation always enters the book at revision 1.
    return {"id": event["id"], "resource": event["resource"], "owner": event["owner"],
            "start": event["start"], "end": event["end"], "revision": 1}


def transferred(current, event):
    # A transfer keeps the ID, rewrites the other facts and bumps the revision.
    return {"id": current["id"], "resource": event["resource"], "owner": event["owner"],
            "start": event["start"], "end": event["end"], "revision": current["revision"] + 1}


def apply(request):
    closed, problem = read_closed(request.get("closed", []))
    if problem:
        return failure(problem)
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    identities, problem = read_events(request.get("events"))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)

    book = dict(active)
    schedule = Schedule.from_rows(ordered)
    shut = Windows.from_rows(closed)
    results = []
    # Everything is staged in memory; the response is only built once the batch
    # is known to be valid, so a later failure leaves no partial booking.
    for index, event in enumerate(request["events"]):
        if identities[index]:
            results.append({"event_id": event["event_id"], "outcome": "replay"})
            continue
        reservation_id = event["id"]
        current = book.get(reservation_id)
        kind = event["kind"]
        if kind == "release":
            if current is None:
                return failure("unknown-reservation", index)
            del book[reservation_id]
            schedule.remove(current["resource"], current["start"], current["end"], reservation_id)
            results.append({"event_id": event["event_id"], "outcome": "applied"})
            continue
        if kind == "reserve":
            if current is not None:
                return failure("duplicate-reservation", index)
            if shut.closed(event["resource"], event["start"], event["end"]):
                return failure("window-closed", index)
            if schedule.conflicts(event["resource"], event["start"], event["end"]):
                return failure("overlap", index)
            row = reserve(event)
            book[reservation_id] = row
            schedule.add(row["resource"], row["start"], row["end"], reservation_id)
            results.append({"event_id": event["event_id"], "outcome": "applied"})
            continue
        # transfer: presence and revision first, then the closed windows and
        # overlaps of the destination, which never include the moved booking.
        if current is None or current["revision"] != event["if_revision"] \
                or current["revision"] >= MAX_VALUE:
            return failure("revision-conflict", index)
        if shut.closed(event["resource"], event["start"], event["end"]):
            return failure("window-closed", index)
        schedule.remove(current["resource"], current["start"], current["end"], reservation_id)
        if schedule.conflicts(event["resource"], event["start"], event["end"]):
            return failure("overlap", index)
        row = transferred(current, event)
        book[reservation_id] = row
        schedule.add(row["resource"], row["start"], row["end"], reservation_id)
        results.append({"event_id": event["event_id"], "outcome": "applied",
                        "fromRevision": current["revision"], "toRevision": row["revision"]})

    return {"status": "ok",
            "active": sorted(book.values(), key=sort_key),
            "results": results}


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation == "inspect":
        if request.keys() - {"operation", "active"}:
            return failure("invalid-request")
        return inspect(request)
    if operation == "apply":
        if request.keys() - {"operation", "active", "events", "closed"}:
            return failure("invalid-request")
        return apply(request)
    return failure("invalid-request")

