"""Check reservations and closed windows for a resource's time intervals."""

from bisect import bisect_left, bisect_right

MAX_CLOSED = 24_000
MAX_VALUE = 1_000_000_000
CLOSED_FIELDS = {"resource", "start", "end"}


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value):
    # Python bool subclasses int, but JSON booleans are invalid time values.
    return type(value) is int and 0 <= value <= MAX_VALUE


def read_closed(value):
    """Validate the optional ``closed`` list of suspension windows.

    Windows may overlap or arrive unordered, so each one is checked on its own;
    only the shape, not any relationship between windows, is constrained here.
    """
    if not isinstance(value, list) or len(value) > MAX_CLOSED:
        return None, "invalid-window"
    for window in value:
        if (not isinstance(window, dict) or window.keys() != CLOSED_FIELDS
                or not name(window["resource"])
                or not integer(window["start"]) or not integer(window["end"])
                or window["start"] >= window["end"]):
            return None, "invalid-window"
    return value, None


def first_overlap(ordered_rows):
    # A sorted sweep needs only the end of the latest reservation for each resource.
    previous_resource, previous_end = None, None
    for row in ordered_rows:
        if row["resource"] == previous_resource and row["start"] < previous_end:
            return "overlap"
        previous_resource, previous_end = row["resource"], row["end"]
    return None


class Schedule:
    """Per-resource interval index over left-closed, right-open reservation spans.

    Each resource keeps its spans sorted by start with the furthest ``end`` of
    every prefix cached, so a conflict check, insert or removal costs
    ``O(log n)`` per resource instead of rescanning the whole book.
    """

    def __init__(self):
        self._resources = {}

    @classmethod
    def from_rows(cls, rows):
        schedule = cls()
        for row in rows:
            schedule._resource(row["resource"]).insert(row["start"], row["end"], row["id"])
        return schedule

    def _resource(self, resource):
        band = self._resources.get(resource)
        if band is None:
            band = self._resources[resource] = _Band()
        return band

    def conflicts(self, resource, start, end):
        band = self._resources.get(resource)
        return band is not None and band.conflicts(start, end)

    def add(self, resource, start, end, reservation_id):
        self._resource(resource).insert(start, end, reservation_id)

    def remove(self, resource, start, end, reservation_id):
        self._resources[resource].remove(start, end, reservation_id)


class Windows:
    """Per-resource index of closed windows over the same left-closed half-open convention.

    Frozen once built: the batch never adds or removes a window, so each band is
    swept into canonical, non-touching order so a probe costs ``O(log n)``.
    """

    def __init__(self, rows=()):
        self._resources = {}
        self._build(rows)

    @classmethod
    def from_rows(cls, rows):
        return cls(rows)

    def _build(self, rows):
        for row in rows:
            self._resources.setdefault(row["resource"], []).append((row["start"], row["end"]))
        for resource, spans in self._resources.items():
            self._resources[resource] = _merge(spans)

    def closed(self, resource, start, end):
        spans = self._resources.get(resource)
        if spans is None:
            return False
        # Spans are disjoint and sorted, so only the one starting last on or
        # before ``end`` can cover any part of ``[start, end)``.
        position = bisect_right(spans, (end,)) - 1
        return position >= 0 and spans[position][1] > start


def _merge(spans):
    # Overlapping windows that name the same resource are one closed region.
    spans.sort()
    merged = []
    for start, end in spans:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


class _Band:
    """Ordered spans ``[start, end)`` for one resource with prefix maxima of ``end``."""

    __slots__ = ("keys", "starts", "ends", "peak")

    def __init__(self):
        self.keys = []   # (start, end, reservation_id), sorted
        self.starts = []  # the start column of ``keys``, the search bench
        self.ends = []
        self.peak = []    # running maximum of ``ends``

    def conflicts(self, start, end):
        # A stored span ``[s, e)`` overlaps ``[start, end)`` iff ``s < end`` and
        # ``start < e``. Spans are sorted by ``s``, so the ones with ``s < end``
        # form a prefix (``bisect_left``, since ``s == end`` merely touches);
        # inside that prefix a conflict exists iff some ``e > start``, which the
        # prefix maxima answer in one more bisect.
        limit = bisect_left(self.starts, end)
        return bisect_right(self.peak, start, 0, limit) != limit

    def insert(self, start, end, reservation_id):
        index = bisect_right(self.starts, start)
        self.keys.insert(index, (start, end, reservation_id))
        self.starts.insert(index, start)
        self.ends.insert(index, end)
        top = end if index == 0 else max(self.peak[index - 1], end)
        self.peak.insert(index, top)
        # Raising one ceiling raises every later prefix that it now exceeds.
        for position in range(index + 1, len(self.peak)):
            if self.peak[position] >= top:
                break
            self.peak[position] = top

    def remove(self, start, end, reservation_id):
        target = bisect_left(self.keys, (start, end, reservation_id))
        if target == len(self.keys) or self.keys[target] != (start, end, reservation_id):
            raise KeyError("reservation not indexed")
        del self.keys[target]
        del self.starts[target]
        del self.ends[target]
        del self.peak[target]
        for position in range(target, len(self.peak)):
            # Peaks only ever fall, so recomputation stops at the first stable entry.
            peak = self.peak[position] if position == 0 else max(self.peak[position - 1],
                                                                 self.ends[position])
            if peak == self.peak[position]:
                break
            self.peak[position] = peak

