    """Return the normalized event and its identity, or (None, code).

    Shape is checked before identity on purpose: a duplicate event that is also
    malformed must report ``invalid-event``, not be treated as a retry.
    """
    if not isinstance(event, dict):
        return None, "invalid-event"
    kind = event.get("kind")
    if kind == "reserve":
        if (event.keys() != RESERVE_FIELDS or not name(event["event_id"])
                or not all(name(event[key]) for key in ("id", "resource", "owner"))
                or not integer(event["start"]) or not integer(event["end"])
                or event["start"] >= event["end"]):
            return None, "invalid-event"
        identity = ("reserve", event["id"], event["resource"], event["owner"],
                    event["start"], event["end"])
        normalized = {"kind": kind, "event_id": event["event_id"], "id": event["id"],
                      "resource": event["resource"], "owner": event["owner"],
                      "start": event["start"], "end": event["end"]}
    elif kind == "release":
        if event.keys() != RELEASE_FIELDS or not name(event["event_id"]) or not name(event["id"]):
            return None, "invalid-event"
        identity = ("release", event["id"])
        normalized = {"kind": kind, "event_id": event["event_id"], "id": event["id"]}
    else:
        return None, "invalid-event"
    # The normalized event carries only validated values, so ledger never has to
    # trust or re-read the caller's mapping.
    normalized["identity"] = identity
    return normalized, None


