"""Validate immutable reservation records at the input boundary."""

MAX_VALUE = 1_000_000_000
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
RELEASE_FIELDS = {"event_id", "kind", "id"}
TRANSFER_FIELDS = RESERVE_FIELDS | {"if_revision"}
WINDOW_FIELDS = {"resource", "start", "end"}
MAX_EVENTS = 4096
MAX_CLOSED = 24000


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def interval_ok(value):
    """Two integer time points with 0 <= start < end <= 1e9."""
    return (integer(value["start"]) and integer(value["end"])
            and value["start"] < value["end"])


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def read_events(value):
    """Validate the batch container only; each item is checked in input order.

    Checking the container here keeps apply's failure order intact: a malformed
    events list is a request-shape problem, while a malformed single event is an
    event problem carrying its own eventIndex.
    """
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
        return "invalid-request"
    return None


def read_closed(value):
    """Validate the optional closed-window list; return normalized rows.

    Shape errors are ``invalid-window`` (not ``invalid-event``) because a window
    is request data, not an event: it is checked once, before event 0, so its
    error always precedes any per-event error and never carries an eventIndex.
    Windows may overlap and be unordered, so no ordering or overlap rule applies.
    """
    if not isinstance(value, list) or len(value) > MAX_CLOSED:
        return None, "invalid-window"
    windows = []
    for window in value:
        if (not isinstance(window, dict) or window.keys() != WINDOW_FIELDS
                or not name(window["resource"]) or not interval_ok(window)):
            return None, "invalid-window"
        windows.append((window["resource"], window["start"], window["end"]))
    return windows, None


def target_ok(event, fields):
    """The fields a reserve and a transfer share: event_id plus the new target."""
    return (event.keys() == fields and name(event["event_id"])
            and all(name(event[key]) for key in ("id", "resource", "owner"))
            and interval_ok(event))


def read_event(event):
    """Return the normalized event and its identity, or (None, code).

    Shape is checked before identity on purpose: a duplicate event that is also
    malformed must report ``invalid-event``, not be treated as a retry.
    """
    if not isinstance(event, dict):
        return None, "invalid-event"
    kind = event.get("kind")
    if kind == "reserve":
        if not target_ok(event, RESERVE_FIELDS):
            return None, "invalid-event"
        identity = ("reserve", event["id"], event["resource"], event["owner"],
                    event["start"], event["end"])
    elif kind == "release":
        if event.keys() != RELEASE_FIELDS or not name(event["event_id"]) or not name(event["id"]):
            return None, "invalid-event"
        identity = ("release", event["id"])
    elif kind == "transfer":
        # if_revision follows the old revision rule: an integer 1..1e9, bools out.
        if not target_ok(event, TRANSFER_FIELDS) or not integer(event["if_revision"], 1):
            return None, "invalid-event"
        # if_revision is part of the identity: the same event_id with a
        # different expected revision is a different request, not a retry.
        identity = ("transfer", event["id"], event["resource"], event["owner"],
                    event["start"], event["end"], event["if_revision"])
    else:
        return None, "invalid-event"
    # The normalized event carries only validated values, so ledger never has to
    # trust or re-read the caller's mapping.
    normalized = {"kind": kind, "event_id": event["event_id"], "id": event["id"]}
    if kind != "release":
        normalized.update(resource=event["resource"], owner=event["owner"],
                          start=event["start"], end=event["end"])
    if kind == "transfer":
        normalized["if_revision"] = event["if_revision"]
    normalized["identity"] = identity
    return normalized, None


class EventBatch:
    """Identities of event_ids seen so far in this batch.

    Identity ignores object field order because it is built from named fields,
    never from the source mapping.  Only one outcome per event_id is possible:
    either it is new, or it exactly matches the recorded one (replay), or the
    content differs (conflicting-event).
    """

    __slots__ = ("seen",)

    def __init__(self):
        self.seen = {}

    def claim(self, event_id, identity):
        """Return ``applied``/``replay`` or ``None`` on conflict.

        A replay is decided here and never re-validates against ledger state, so
        an event whose effect was later released still reports ``replay``.
        """
        previous = self.seen.get(event_id)
        if previous is None:
            self.seen[event_id] = identity
            return "applied"
        if previous == identity:
            return "replay"
        return None

