    else:
        return None, "invalid-event"
    # The normalized event carries only validated values, so ledger never has to
    # trust or re-read the caller's mapping.
    normalized = {"kind": kind, "event_id": event["event_id"], "id": event["id"]}
    if kind != "release":
        normalized.update(resource=event["resource"], owner=event["owner"],
                          start=event["start"], end=event["end"])
    if kind == "transfer":
        normalized["if_revision"] = event["if_revision"]
    normalized["identity"] = identity
    return normalized, None


class EventBatch:
    """Identities of event_ids seen so far in this batch.

    Identity ignores object field order because it is built from named fields,
    never from the source mapping.  Only one outcome per event_id is possible:
    either it is new, or it exactly matches the recorded one (replay), or the
    content differs (conflicting-event).
    """

    __slots__ = ("seen",)

    def __init__(self):
        self.seen = {}

    def claim(self, event_id, identity):
        """Return ``applied``/``replay`` or ``None`` on conflict.

        A replay is decided here and never re-validates against ledger state, so
        an event whose effect was later released still reports ``replay``.
        """
        previous = self.seen.get(event_id)
        if previous is None:
            self.seen[event_id] = identity
            return "applied"
        if previous == identity:
            return "replay"
        return None

