"""Process a decoded request without reading any transport or disk state."""
from events import (MAX_VALUE, EventBatch, read_active, read_closed, read_event,
                    read_events)
from windows import ResourceIndex, build_windows, first_overlap, sort_key


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


class Ledger:
    """Mutable working state for one apply batch.

    ``records`` is the dict returned by read_active, freshly built for this
    request; this class additionally copies every row (see below) so the batch
    never aliases the caller's objects.  A failure can therefore simply drop the
    dict: there is no earlier state to restore and no partial result to leak.
    """

    __slots__ = ("records", "resources", "closed")

    def __init__(self, records, windows):
        # The transfer mutates its target row in place.  Rows come straight from
        # the decoded request, and callers may reuse that request (tests, the
        # verify cross-check, an embedding harness), so every row is copied once
        # here.  This is what makes "the input is never modified" hold at all,
        # not merely a safety net: without it a failed batch would also leave
        # the caller's own active list corrupted.
        for rid, row in records.items():
            records[rid] = dict(row)
        self.records = records
        # Index every resource once up front (O(n log n)); afterwards each event
        # costs O(log n) instead of scanning all reservations.
        self.resources = {}
        by_resource = {}
        for row in records.values():
            by_resource.setdefault(row["resource"], []).append(row)
        for resource, rows in by_resource.items():
            index = ResourceIndex()
            for row in rows:
                index.add(row)
            self.resources[resource] = index
        # Windows are normalised against the live set as it is *now*; see
        # WindowIndex for why the merge depends on it and stays correct later.
        self.closed = build_windows(windows, by_resource.keys())

    def _index(self, resource):
        index = self.resources.get(resource)
        if index is None:
            index = self.resources[resource] = ResourceIndex()
        return index

    def _blocked(self, resource, start, end):
        """window-closed check; always asked before the reservation overlap."""
        window = self.closed.get(resource)
        return window is not None and window.covers(start, end)

    def reserve(self, event):
        # Checked before the interval: an id that is already live wins over any
        # overlap, so the reported code does not depend on unrelated intervals.
        if event["id"] in self.records:
            return "duplicate-reservation"
        # Then the closure, then the reservations: a request inside a closed
        # window reports window-closed even if it also collides, which is the
        # documented priority and keeps the code stable as reservations change.
        if self._blocked(event["resource"], event["start"], event["end"]):
            return "window-closed"
        if self._index(event["resource"]).overlaps(event["start"], event["end"]):
            return "overlap"
        row = {"id": event["id"], "resource": event["resource"], "owner": event["owner"],
               "start": event["start"], "end": event["end"], "revision": 1}
        self.records[row["id"]] = row
        self._index(row["resource"]).add(row)
        return None

    def release(self, event):
        # Releases ignore windows entirely: a closure forbids new placements, it
        # does not freeze what is already placed inside it.
        row = self.records.pop(event["id"], None)
        if row is None:
            return "unknown-reservation"
        self._index(row["resource"]).remove(row)
        return None

    def transfer(self, event, target):
        """Replace a reservation with the transfer's target and bump its revision.

        Returns (None, from_revision, to_revision) or (code, None, None).
        ``target`` is a fresh dict, never the caller's event mapping, so the
        row mutation below cannot reach the request.
        """
        current = self.records.get(event["id"])
        # Revision before windows and overlaps: a stale writer must be told it is
        # stale even if its target is also forbidden, so a caller can retry by
        # re-reading and never has to interpret a window error as a lost update.
        if current is None or current["revision"] != event["if_revision"]:
            return "revision-conflict", None, None
        to_revision = event["if_revision"] + 1
        # if_revision is validated as <= 1e9, so at 1e9 the bump would leave the
        # revision domain; the format would be unsatisfiable, so the existing
        # conflict code is reused rather than inventing one.
        if to_revision > MAX_VALUE:
            return "revision-conflict", None, None
        # The replaced row is excluded from the overlap check by ``target``, but
        # it is not moved yet: the checks must run before any state changes so a
        # rejected transfer leaves the working batch untouched.
        if self._blocked(target["resource"], target["start"], target["end"]):
            return "window-closed", None, None
        if self._index(target["resource"]).overlaps(target["start"], target["end"],
                                                    ignore_id=event["id"]):
            return "overlap", None, None
        # The row may be indexed under a different resource.  Drop the stale
        # entry first: leaving it behind would make a later event collide with a
        # reservation that has already left that resource.  Removal and re-add
        # are both bisect operations; there is no rollback because every failure
        # return happens above this line.
        self._index(current["resource"]).remove(current)
        current["resource"] = target["resource"]
        current["owner"] = target["owner"]
        current["start"] = target["start"]
        current["end"] = target["end"]
        current["revision"] = to_revision
        self._index(current["resource"]).add(current)
        return None, event["if_revision"], to_revision

    def ordered(self):
        return sorted(self.records.values(), key=sort_key)


def apply(request, records, windows):
    ledger = Ledger(records, windows)
    batch = EventBatch()
    results = []
    for index, raw in enumerate(request["events"]):
        event, problem = read_event(raw)
        if problem:
            # Order matters: shape, then identity, then business.  A retried
            # event skips the business step entirely, so replay stays idempotent
            # even when its original effect has since been released.
            return failure(problem, index)
        outcome = batch.claim(event["event_id"], event["identity"])
        if outcome is None:
            return failure("conflicting-event", index)
        if outcome == "applied":
            kind = event["kind"]
            if kind == "reserve":
                problem = ledger.reserve(event)
            elif kind == "release":
                problem = ledger.release(event)
            else:
                problem, from_revision, to_revision = ledger.transfer(
                    event, {key: event[key] for key in ("resource", "owner", "start", "end")})
            if problem:
                return failure(problem, index)
        # A replay reports only event_id and outcome: the transfer extras belong
        # to the event that actually moved the reservation, not to retries.
        if kind == "transfer" and outcome == "applied":
            results.append({"event_id": event["event_id"], "outcome": outcome,
                            "fromRevision": from_revision, "toRevision": to_revision})
        else:
            results.append({"event_id": event["event_id"], "outcome": outcome})
    # Reaching here means the whole batch succeeded; only now is the working
    # state turned into a response, so a failure above never returns a prefix.
    return {"status": "ok", "active": ledger.ordered(), "results": results}


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation == "inspect":
        if request.keys() - {"operation", "active"}:
            return failure("invalid-request")
        active, problem = read_active(request.get("active", []))
        if problem:
            return failure(problem)
        ordered = sorted(active.values(), key=sort_key)
        problem = first_overlap(ordered)
        if problem:
            return failure(problem)
        return {"status": "ok", "active": ordered, "results": []}
    if operation == "apply":
        if request.keys() - {"operation", "active", "events", "closed"}:
            return failure("invalid-request")
        active, problem = read_active(request.get("active", []))
        if problem:
            return failure(problem)
        # Windows are validated before any event is read, so invalid-window
        # outranks every per-event error regardless of which event is bad.
        windows, problem = read_closed(request.get("closed", []))
        if problem:
            return failure(problem)
        # active is validated before the events container, matching the spec's
        # "once active is valid" ordering.
        problem = read_events(request.get("events"))
        if problem:
            return failure(problem)
        return apply(request, active, windows)
    return failure("invalid-request")

