"""Validate immutable reservation records and batch events at the input boundary."""

MAX_VALUE = 1_000_000_000
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
TRANSFER_FIELDS = RESERVE_FIELDS | {"if_revision"}
RELEASE_FIELDS = {"event_id", "kind", "id"}
MAX_EVENTS = 4096


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def _fingerprint(row):
    # Tuple of (field, value) pairs sorted by field, so the identity fingerprint
    # covers every supplied field and is stable under JSON object key order.
    return tuple(sorted(row.items()))


def check_event_batch(value):
    """Check only the batch envelope: events must be a list of 1 to 4096 items.

    Element validation is deliberately *not* done here. A whole-batch pre-scan
    would let a late shape or identity fault outrank an earlier business error,
    so shape -> identity -> business has to be interleaved per item by the
    caller; see check_event.
    """
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
        return "invalid-request"
    return None


def check_event(row, index, seen):
    """Shape-check one event, then settle its event_id identity against `seen`.

    Returns an error code or None. `seen` maps event_id to the identity
    fingerprint of its first occurrence; an identical later record is a retry
    the caller reports as replay, a differing one is `conflicting-event`. Shape
    precedes identity so a malformed item is never blamed for a conflict.
    """
    if not isinstance(row, dict):
        return "invalid-event"
    kind = row.get("kind")
    if type(kind) is not str or not name(row.get("event_id")):
        return "invalid-event"
    if kind == "reserve":
        if (row.keys() != RESERVE_FIELDS
                or not name(row["id"]) or not name(row["resource"])
                or not name(row["owner"]) or not integer(row["start"])
                or not integer(row["end"]) or row["start"] >= row["end"]):
            return "invalid-event"
    elif kind == "transfer":
        if (row.keys() != TRANSFER_FIELDS
                or not name(row["id"]) or not name(row["resource"])
                or not name(row["owner"]) or not integer(row["start"])
                or not integer(row["end"]) or row["start"] >= row["end"]
                or not integer(row["if_revision"], 1)):
            return "invalid-event"
    elif kind == "release":
        if row.keys() != RELEASE_FIELDS or not name(row["id"]):
            return "invalid-event"
    else:
        return "invalid-event"
    fingerprint = _fingerprint(row)
    previous = seen.setdefault(row["event_id"], fingerprint)
    if previous != fingerprint:
        return "conflicting-event"
    return None

