"""Process a decoded request without reading any transport or disk state."""
import bisect

from events import MAX_VALUE, check_event, check_event_batch, read_active
from windows import first_overlap, read_closed, touches_closed

INSPECT_KEYS = {"operation", "active"}
APPLY_KEYS = {"operation", "active", "events", "closed"}


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


class Schedule:
    """Per-resource interval index plus the live reservation table for one batch.

    Two structures are kept in step: `records` maps reservation id to its row,
    and `spans` maps resource to the sorted list of (start, end, id) of the live
    reservations on that resource. Checking one candidate therefore costs a
    binary search instead of a scan of all 24,000 active rows; correctness relies
    on every mutation going through add/remove so the two never drift apart.
    """

    def __init__(self, records):
        # Rows are copied so a failed batch cannot leak edits to the caller's input.
        self.records = {key: dict(row) for key, row in records.items()}
        self.spans = {}
        for row in self.records.values():
            self.spans.setdefault(row["resource"], []).append(
                (row["start"], row["end"], row["id"]))
        for spans in self.spans.values():
            spans.sort()

    def add(self, row):
        self.records[row["id"]] = row
        spans = self.spans.setdefault(row["resource"], [])
        bisect.insort(spans, (row["start"], row["end"], row["id"]))

    def remove(self, reservation_id):
        row = self.records.pop(reservation_id)
        spans = self.spans[row["resource"]]
        spans.pop(bisect.bisect_left(spans, (row["start"], row["end"], reservation_id)))
        return row

    def collides(self, resource, start, end, ignore_id):
        """True when [start, end) intersects a live reservation on that resource.

        ignore_id skips the row being replaced by a transfer, because a transfer
        never conflicts with itself.
        """
        spans = self.spans.get(resource)
        if spans is None:
            return False
        # Only spans starting before `end` can intersect. Walking back from that
        # cut stops at the first span ending at or before `start`, so the cost is
        # proportional to the overlaps found and not to the resource size.
        position = bisect.bisect_left(spans, (end,))
        for index in range(position - 1, -1, -1):
            span_start, span_end, span_id = spans[index]
            if span_end <= start:
                break
            if span_id != ignore_id:
                return True
        return False


def apply_events(request):
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    # Closed windows are refused before any event is shaped or applied, so the
    # response cannot depend on how far event processing got.
    closed, problem = read_closed(request.get("closed", []))
    if problem:
        return failure(problem)
    problem = check_event_batch(request.get("events"))
    if problem:
        return failure(problem)
    events = request["events"]
    schedule = Schedule(active)
    results = []
    # Two batch-local tables. `seen` maps event_id to the identity fingerprint of
    # its first occurrence: a later item with the same key and fingerprint is a
    # retry, one with a different fingerprint is refused by check_event. `settled`
    # records the keys already processed so a retry is answered from history
    # alone and never touches reservation state again.
    seen = {}
    settled = {}
    for position, event in enumerate(events):
        # Shape and identity are settled per item, here, rather than in a batch
        # pre-pass: an item's business error must outrank a later item's fault.
        problem = check_event(event, position, seen)
        if problem:
            return failure(problem, position)
