"""Check reservations against other appointments and closed windows for the same resource."""
import bisect


MAX_WINDOWS = 24_000
MAX_VALUE = 1_000_000_000


def _time_point(value):
    # Python bool subclasses int, but JSON booleans are not valid time points.
    # Kept local (not imported from events) because windows owns resource
    # interval validation and the original import direction has no edges here.
    return type(value) is int and 0 <= value <= MAX_VALUE


def read_closed(value):
    """Validate the optional `closed` list before any event is examined.

    Returns (per-resource merged interval index, error code). The index is built
    once per batch so each event's closed check is a binary search instead of a
    rescan of up to 24,000 windows. Windows may overlap or arrive unordered.
    """
    if not isinstance(value, list) or len(value) > MAX_WINDOWS:
        return None, "invalid-window"
    by_resource = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != {"resource", "start", "end"}
                or not isinstance(row["resource"], str) or not 1 <= len(row["resource"]) <= 64
                or not _time_point(row["start"]) or not _time_point(row["end"])
                or row["start"] >= row["end"]):
            return None, "invalid-window"
        by_resource.setdefault(row["resource"], []).append((row["start"], row["end"]))
    index = {}
    for resource, spans in by_resource.items():
        spans.sort()
        merged = [list(spans[0])]
        for start, end in spans[1:]:
            if start <= merged[-1][1]:
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        index[resource] = ([start for start, _ in merged], [end for _, end in merged])
    return index, None


def touches_closed(index, resource, start, end):
    """True when [start, end) intersects a closed window on the same resource.

    Half-open endpoint touching stays legal, matching the reservation rule.
    """
    entry = index.get(resource)
    if entry is None:
        return False
    starts, ends = entry
    position = bisect.bisect_left(starts, end)
    return position > 0 and ends[position - 1] > start


def first_overlap(ordered_rows):
    # A sorted sweep needs only the end of the latest reservation for each resource.
    previous_resource, previous_end = None, None
    for row in ordered_rows:
        if row["resource"] == previous_resource and row["start"] < previous_end:
            return "overlap"
        previous_resource, previous_end = row["resource"], row["end"]
    return None

