"""Process a decoded request without reading any transport or disk state."""
from events import BatchEvents, read_active
from windows import ResourceIndex, first_overlap

APPLY_FIELDS = {"operation", "active", "events"}


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation == "inspect" and not request.keys() - {"operation", "active"}:
        return inspect(request.get("active", []))
    if operation == "apply" and not request.keys() - APPLY_FIELDS:
        return apply(request.get("active", []), request.get("events"))
    return failure("invalid-request")


def inspect(value):
    active, problem = read_active(value)
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def apply(active_value, events_value):
    # Phase 1: the batch's active set. No event is read until this set is valid.
    active, problem = read_active(active_value)
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)

    # Phase 2: every event shape, then every event identity, before any business step.
    events, roles, index, problem = BatchEvents(events_value).plan()
