"""Process a decoded request without reading any transport or disk state."""
from events import MAX_VALUE, BatchEvents, read_active
from windows import ResourceIndex, first_overlap, read_windows

APPLY_FIELDS = {"operation", "active", "events", "closed"}


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation == "inspect" and not request.keys() - {"operation", "active"}:
        return inspect(request.get("active", []))
    if operation == "apply" and not request.keys() - APPLY_FIELDS:
        return apply(request.get("active", []), request.get("events"), request.get("closed", []))
    return failure("invalid-request")


def inspect(value):
    active, problem = read_active(value)
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem is None:
        return {"status": "ok", "active": ordered, "results": []}
    return failure(problem)


def apply(active_value, events_value, closed_value):
    # Phase 1: the closed windows, before any event is read. Existing reservations
    # are judged as they stand; a window only constrains new reserve and transfer.
    windows, problem = read_windows(closed_value)
    if problem:
        return failure(problem)

    # Phase 2: the batch's active set. No event is read until this set is valid.
    # Its overlap sweep runs now, so no event can outrank it; the sorted list is
    # only read after every event passes.
    active, problem = read_active(active_value)
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)

    # Phase 3: every event shape, then every event identity, before any business step.
    events, roles, index, problem = BatchEvents(events_value).plan()
    if problem:
        return failure(problem, index)

    # Phase 4: replay the batch in input order against a working copy. The sorted
    # `ordered` base is never mutated, and nothing is published until every event
    # passes, so a late failure commits no earlier reservation or result.
    reservations = dict(active)
    # The ids whose current row is a row this batch wrote, and those rows keyed by
    # id: `fresh` is what the batch returns for them, merged back in inspect order.
    written, fresh = set(), {}
    # Placement is judged against the reservations the batch itself has committed so
    # far, so a batch is valid only if every step is. The initial active set is not
    # indexed: it is already valid, and a window does not let it block a replacement.
    intervals = ResourceIndex([])
    intervals.finish()
    results = []
    for position, role in enumerate(roles):
        event = events[position]
        if role == "replay":
            results.append({"event_id": event.event_id, "outcome": "replay"})
            continue
        reservation_id = event.id
        if event.kind == "release":
            if reservation_id not in reservations:
                return failure("unknown-reservation", position)
            current = reservations.pop(reservation_id)
            if reservation_id in written:
                written.discard(reservation_id)
                intervals.remove(current["resource"], current["start"], current["end"])
            results.append({"event_id": event.event_id, "outcome": "applied"})
            continue
        if event.kind == "transfer":
            current = reservations.get(reservation_id)
            # The revision guard settles before the target's window or overlap, and
            # a reservation already at the top revision has no next version.
            if (current is None or current["revision"] != event.if_revision
                    or current["revision"] >= MAX_VALUE):
                return failure("revision-conflict", position)
            revision = current["revision"]
            if reservation_id in written:
                intervals.remove(current["resource"], current["start"], current["end"])
            # The reservation stopped competing with itself the moment it was removed.
            code = placement(event, windows, intervals)
            if code:
                return failure(code, position)
            row = {"id": reservation_id, "resource": event.resource, "owner": event.owner,
                   "start": event.start, "end": event.end, "revision": revision + 1}
            reservations[reservation_id] = fresh[reservation_id] = row
            written.add(reservation_id)
            intervals.add(event.resource, event.start, event.end)
            results.append({"event_id": event.event_id, "outcome": "applied",
                            "fromRevision": revision, "toRevision": revision + 1})
            continue
        if reservation_id in reservations:
            return failure("duplicate-reservation", position)
        code = placement(event, windows, intervals)
        if code:
            return failure(code, position)
        row = {"id": reservation_id, "resource": event.resource, "owner": event.owner,
               "start": event.start, "end": event.end, "revision": 1}
        reservations[reservation_id] = fresh[reservation_id] = row
        written.add(reservation_id)
        intervals.add(event.resource, event.start, event.end)
        results.append({"event_id": event.event_id, "outcome": "applied"})

    return {"status": "ok", "active": merged(ordered, fresh), "results": results}


def placement(event, windows, intervals):
    # A closed window is judged before any live reservation overlaps the target.
    if windows.closed(event.resource, event.start, event.end):
        return "window-closed"
    if not intervals.free(event.resource, event.start, event.end):
        return "conflict"
    return None


def merged(ordered, fresh):
    """Return the committed active list in inspect order.

    Untouched rows are already sorted, so only the rows this batch reserved or
    transferred are sorted and merged back in; the rest are copied through. A row
    this batch changed or replaced is carried by its new row, skipped at its old
    position, and an untouched row is passed through as it came.
    """
    if not fresh:
        return ordered
    added = sorted((sort_key(row), reservation_id) for reservation_id, row in fresh.items())
    merged_rows, pointer = [], 0
    for row in ordered:
        if row["id"] in fresh:
            continue
        key = sort_key(row)
        while pointer < len(added) and added[pointer][0] < key:
            merged_rows.append(fresh[added[pointer][1]])
            pointer += 1
        merged_rows.append(row)
    merged_rows.extend(fresh[reservation_id] for _, reservation_id in added[pointer:])
    return merged_rows

