"""Check reservations and closed windows against other intervals for the same resource."""
from bisect import bisect_left, bisect_right

MAX_VALUE = 1_000_000_000
MAX_WINDOWS = 24000
WINDOW_FIELDS = {"resource", "start", "end"}


def first_overlap(ordered_rows):
    # A sorted sweep needs only the end of the latest reservation for each resource.
    previous_resource, previous_end = None, None
    for row in ordered_rows:
        if row["resource"] == previous_resource and row["start"] < previous_end:
            return "overlap"
        previous_resource, previous_end = row["resource"], row["end"]
    return None


def read_windows(value):
    """Validate the optional `closed` list and index it; any problem is invalid-window.

    Each entry has exactly resource, start and end under the reservation field
    rules: a 1 to 64 character name and 0 <= start < end <= 1e9. Windows of one
    resource may overlap each other or arrive out of order; they are only ever
    queried, so they are sorted once after the whole list is read.
    """
    if value is None:
        value = []
    if not isinstance(value, list) or len(value) > MAX_WINDOWS:
        return None, "invalid-window"
    by_resource = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != WINDOW_FIELDS
                or not isinstance(row["resource"], str)
                or not 1 <= len(row["resource"]) <= 64):
            return None, "invalid-window"
        start, end = row["start"], row["end"]
        # Python bool subclasses int, but JSON booleans are invalid time values.
        if (type(start) is not int or type(end) is not int
                or not 0 <= start < end <= MAX_VALUE):
            return None, "invalid-window"
        by_resource.setdefault(row["resource"], []).append((start, end))
    for intervals in by_resource.values():
        intervals.sort()
    return Windows(by_resource), None


class Windows:
    """Each resource's closed intervals, sorted by start and never changed."""

    def __init__(self, by_resource):
        self.by_resource = by_resource

    def closed(self, resource, start, end):
        """True when a closed window of `resource` overlaps the half-open interval."""
        intervals = self.by_resource.get(resource)
        if intervals is None:
            return False
        # Every window starting before `end` is a candidate, and the latest of them
        # decides: one that starts later and reaches past `start` covers the rest.
        position = bisect_left(intervals, (end,))
        return position > 0 and intervals[position - 1][1] > start


class ResourceIndex:
    """Index each resource's live intervals by start so one reservation is checked alone.

    Intervals are half-open, so touching endpoints do not overlap. A resource only
    competes with itself; a batch touching 4096 events never rescans all reservations.
    Rows loaded in bulk are sorted once by finish(), and the intervals a batch adds
    or removes keep every list sorted afterwards.
    """

    def __init__(self, rows):
        self.deferred = []
        self.by_resource = {}
        for row in rows:
            self.deferred.append((row["resource"], row["start"], row["end"]))

    def finish(self):
        """Sort what was loaded, then index every later add or remove one at a time."""
        deferred, self.deferred = self.deferred, None
        for resource, start, end in deferred:
            intervals = self.by_resource.setdefault(resource, [])
            intervals.append((start, end))
        for intervals in self.by_resource.values():
            intervals.sort()

    def free(self, resource, start, end):
        intervals = self.by_resource.get(resource)
        if intervals is None:
            return True
        # Everything after this point starts at or after `start`, so only the
        # predecessor can cover `start`; the next interval may still start too early.
        position = bisect_right(intervals, (start, end))
        if position and intervals[position - 1][1] > start:
            return False
        return position == len(intervals) or intervals[position][0] >= end

    def add(self, resource, start, end):
        if self.deferred is not None:
            self.deferred.append((resource, start, end))
            return
        intervals = self.by_resource.setdefault(resource, [])
        intervals.insert(bisect_right(intervals, (start, end)), (start, end))

    def remove(self, resource, start, end):
        intervals = self.by_resource[resource]
        del intervals[bisect_right(intervals, (start, end)) - 1]
        if not intervals:
            del self.by_resource[resource]

