    """Return the committed active list in inspect order.

    Untouched rows are already sorted, so only the rows this batch reserved or
    transferred are sorted and merged back in; the rest are copied through. A row
    this batch changed or replaced is carried by its new row, skipped at its old
    position, and an untouched row is passed through as it came.
    """
    if not fresh:
        return ordered
    added = sorted((sort_key(row), reservation_id) for reservation_id, row in fresh.items())
    merged_rows, pointer = [], 0
    for row in ordered:
        if row["id"] in fresh:
            continue
        key = sort_key(row)
        while pointer < len(added) and added[pointer][0] < key:
            merged_rows.append(fresh[added[pointer][1]])
            pointer += 1
        merged_rows.append(row)
    merged_rows.extend(fresh[reservation_id] for _, reservation_id in added[pointer:])
    return merged_rows

