"""Validate immutable reservation records and batch events at the input boundary."""
import json

from windows import MAX_VALUE

MAX_EVENTS = 4096
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
RELEASE_FIELDS = {"event_id", "kind", "id"}
TRANSFER_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end", "if_revision"}


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def read_event(value):
    """Return a spot for the event in one batch list: its source item plus its shape."""

    class Item:
        __slots__ = ("source", "event_id", "kind", "id", "resource", "owner", "start", "end",
                     "if_revision")

        def __init__(self, source, event_id, kind, reservation_id,
                     resource=None, owner=None, start=None, end=None, if_revision=None):
            self.source = source
            self.event_id = event_id
            self.kind = kind
            self.id = reservation_id
            self.resource = resource
            self.owner = owner
            self.start = start
            self.end = end
            self.if_revision = if_revision

    if not isinstance(value, dict):
        return None
    event_id, kind = value.get("event_id"), value.get("kind")
    if not name(event_id):
        return None
    if kind == "reserve":
        if (value.keys() != RESERVE_FIELDS
                or not all(name(value[key]) for key in ("id", "resource", "owner"))
                or not integer(value["start"]) or not integer(value["end"])
                or value["start"] >= value["end"]):
            return None
        return Item(value, event_id, kind, value["id"], value["resource"], value["owner"],
                    value["start"], value["end"])
    if kind == "release":
        if value.keys() != RELEASE_FIELDS or not name(value["id"]):
            return None
        return Item(value, event_id, kind, value["id"])
    if kind == "transfer":
        # A transfer replaces one reservation's fields; if_revision follows revision's rule.
        if (value.keys() != TRANSFER_FIELDS
                or not all(name(value[key]) for key in ("id", "resource", "owner"))
                or not integer(value["start"]) or not integer(value["end"])
                or value["start"] >= value["end"]
                or not integer(value["if_revision"], 1)):
            return None
        return Item(value, event_id, kind, value["id"], value["resource"], value["owner"],
                    value["start"], value["end"], value["if_revision"])
    return None


def identity(event):
    """Serialize an event by content, so object field order cannot change its identity."""
    return json.dumps(event, ensure_ascii=True, sort_keys=True, separators=(",", ":"))

class BatchEvents:
    """Track event identities for one batch only; nothing survives the request."""

    def __init__(self, value):
        self.value = value
        self.seen = {}

    def plan(self):
        """Check every event shape first, then every identity, and return each item's role.

        Returns (items, roles, problem_index, problem_code). The code is judged here
        because event validation and event identity are this module's. Items are
        aligned with the input, so roles[index] describes the event at that position.
        Verification stops at the first problem, but it never gets ahead of itself:
        every shape is known before any identity is judged.
        """
        value = self.value
        if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
            return None, None, None, "invalid-request"
        items = []
        for item in value:
            event = read_event(item)
            if event is None:
                return None, None, len(items), "invalid-event"
            items.append(event)
        roles, seen = [], self.seen
        for index, event in enumerate(items):
            event_id, digest = event.event_id, identity(event.source)
            known = seen.get(event_id)
            if known is None:
                seen[event_id] = digest
                roles.append("valid")
            elif known == digest:
                roles.append("replay")
            else:
                return None, None, index, "conflicting-event"
        return items, roles, None, None

