"""Process a decoded request without reading any transport or disk state.

ledger owns ordering and the transaction.  It never decides record/event shape
(events.py) or interval legality (windows.py); it only decides what to ask, in
which order, and when the staged book may be published.
"""
from events import read_active, read_events
from windows import IntervalIndex, first_overlap

OPERATIONS = {"inspect": {"operation", "active"},
