"""Process a decoded request without reading any transport or disk state.

ledger owns ordering and the transaction.  It never decides record/event/window
shape (events.py) or interval legality (windows.py); it only decides what to ask,
in which order, and when the staged book may be published.
"""
from events import MAX_VALUE, read_active, read_closed, read_events
from windows import ClosedIndex, IntervalIndex, first_overlap
from windows import read_closed as read_closed_spans

OPERATIONS = {"inspect": {"operation", "active"},
              "apply": {"operation", "active", "events", "closed"}}


def failure(code, index=None):
    # A fresh object per call: callers cannot corrupt later responses by mutating
    # what they received.
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    # "operation" need not be present for inspect: a missing key is simply an
    # unsupported operation, which SPEC already maps to invalid-request.
    # ``closed`` is only listed for apply, so an inspect request carrying it is an
    # extra top-level field -> invalid-request: CHANGE-G2 keeps inspect's request
    # shape unchanged.
    if operation not in OPERATIONS or request.keys() - OPERATIONS[operation]:
        return failure("invalid-request")
    if operation == "apply" and "events" not in request:
        # SPEC types events as a required list; a missing key is a request-level
        # defect, not a defect of any single event, so eventIndex stays null.
        return failure("invalid-request")
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    if operation == "apply":
        return apply_events(active, request["events"], request.get("closed", []))
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def apply_events(active, raw_events, raw_closed):
    # Phase 0: closed windows.  Both gates report invalid-window and both run
    # before a single event is read, so a bad window outranks every event error
    # (CHANGE-G2: "window errors precede any per-item event error").  ``read_closed``
    # from events.py checks the row shape; windows.py then decides whether the rows
    # are a legal interval set.  eventIndex stays null: no item is to blame.
    # events.read_closed passes a non-list through unchanged, so the list check
    # below is what turns "" / {} / null into invalid-window.
    if not isinstance(raw_closed, list):
        return failure("invalid-window")
    rows = read_closed(raw_closed)
    if rows is None:
        return failure("invalid-window")
    spans = read_closed_spans(rows)
    if spans is None:
        return failure("invalid-window")
    # Built once and reused read-only by every event: windows never change during
    # a batch, so there is no staged copy to maintain.
    closed = ClosedIndex(spans)

    # Phase 1: every shape and identity error in the batch is raised before any
    # business rule runs.  This is what gives SPEC's precedence: business checks
    # are index-ordered in phase 2, and these are index-ordered in phase 1, so
    # "the earliest business error wins" holds inside phase 2 while any
    # invalid-event/conflicting-event outranks all of them.
    entries, problem = read_events(raw_events)
    if problem:
        return failure(problem[0], problem[1])

    # Phase 2: apply in input order against a private copy.  ``book`` maps id to
    # the staged record and the index mirrors the same records by resource, so a
    # release only touches its own intervals instead of rescanning the book.
    # Each staged record is a *shallow copy* of the caller's dict: release only
    # deletes from ``book``, but transfer mutates the record in place (re-indexing
    # is by object identity), so sharing the caller's dicts would rewrite the
    # caller's ``active`` list on the success path.
    book = {rid: dict(record) for rid, record in active.items()}
    index = IntervalIndex(book.values())
    results = []
    for position, (event, replay) in enumerate(entries):
        event_id = event["event_id"]
        if replay:
            # A retry must not move anything, must not increment a revision, and
            # must not report fromRevision/toRevision: the old result in SPEC is
            # exactly {event_id, outcome}.
            results.append({"event_id": event_id, "outcome": "replay"})
            continue
        kind = event["kind"]
        if kind == "reserve":
            code, extra = reserve(book, index, closed, event), None
        elif kind == "release":
            code, extra = release(book, index, event), None
        else:
            code, extra = transfer(book, index, closed, event)
        if code:
            # Atomic failure: nothing accumulated so far leaves this function.
