    reservation_id = event["id"]
    if reservation_id in book:
        return "duplicate-reservation"
    # Stopped first, overlap second: a closed window outranks a booked conflict
    # (CHANGE-G2).  Both checks read the *staged* book/index, never the input
    # snapshot: a release earlier in this batch frees its interval, and a reserve
    # earlier in this batch occupies one.
    if closed.intersects(event["resource"], event["start"], event["end"]):
        return "window-closed"
    if index.find_conflict(event["resource"], event["start"], event["end"]):
        return "overlap"
    record = {key: event[key] for key in ("id", "resource", "owner", "start", "end")}
    record["revision"] = 1
    book[reservation_id] = record
    index.add(record)
    return None


def release(book, index, event):
    # Closing a resource does not freeze what is already booked there: release
    # works exactly as before and never consults ``closed``.
    record = book.get(event["id"])
    if record is None:
        return "unknown-reservation"
    del book[event["id"]]
    index.remove(record)
    return None


def transfer(book, index, closed, event):
    record = book.get(event["id"])
    if record is None:
        return "unknown-reservation", None
    current = record["revision"]
    # The revision guard must come before window and overlap checks (CHANGE-G2).
    # The upper bound is explicit because a successful transfer would otherwise
    # produce revision 1_000_000_001, which read_active would reject on the way
    # back in -- i.e. the ledger would emit a book it could not read itself.
    if current != event["if_revision"] or current >= MAX_VALUE:
        return "revision-conflict", None
    resource, start, end = event["resource"], event["start"], event["end"]
    if closed.intersects(resource, start, end):
        return "window-closed", None
    # ``exclude`` keeps the reservation from colliding with its own old slot; the
    # check covers both the old resource and the new one via find_conflict itself
    # (the record is still indexed under its old resource at this point).
    if index.find_conflict(resource, start, end, exclude=record):
        return "overlap", None
    old_resource = record["resource"]
    # Re-index under the new range/resource.  Removal matches by object identity,
    # so the staged record must be the very dict the index holds: mutate it in
    # place, and only after every check above has passed.  Nothing before this
    # point touched book or index, which is what makes a failed transfer free.
    index.remove(record)
    record["resource"], record["owner"] = resource, event["owner"]
    record["start"], record["end"] = start, end
    record["revision"] = current + 1
    index.add(record)
    return None, {"fromRevision": current, "toRevision": current + 1}

