"""Validate immutable reservation records and events at the input boundary."""
import json

MAX_VALUE = 1_000_000_000
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
RELEASE_FIELDS = {"event_id", "kind", "id"}
MAX_EVENTS = 4096


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def read_event(raw):
    """Return (event, problem) for one raw event; shape only, never current reservation state.

    ledger applies the business rules (duplicate-reservation, unknown-reservation) itself so
    that per-item ordering stays shape, then identity, then business as SPEC.md:9 requires.
    """
    if not isinstance(raw, dict):
        return None, "invalid-event"
    kind = raw.get("kind")
    if kind == "reserve":
        if raw.keys() != RESERVE_FIELDS:
            return None, "invalid-event"
        if (not name(raw["id"]) or not name(raw["resource"]) or not name(raw["owner"])
                or not integer(raw["start"]) or not integer(raw["end"])
                or raw["start"] >= raw["end"]):
            return None, "invalid-event"
    elif kind == "release":
        if raw.keys() != RELEASE_FIELDS or not name(raw["id"]):
            return None, "invalid-event"
    else:
        return None, "invalid-event"
    if not name(raw["event_id"]):
        return None, "invalid-event"
    return raw, None


def fingerprint(event):
    """Content identity of a shape-valid event, independent of the object's field order.

    Sorting keys before serializing makes {kind.., id..} and {id.., kind..} compare equal, which
    SPEC.md:9 requires for replay detection. read_event has already restricted every value to a
    string or an int, so the sorted-key dump identifies content unambiguously.
    """
    return json.dumps(event, sort_keys=True, separators=(",", ":"))

