APPLY_FIELDS = {"operation", "active", "events"}
APPLY_FIELDS_OPTIONAL = {"closed"}


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


class IntervalIndex:
    """Per-resource ordered index of occupied [start, end) intervals.

    Without it, every reserve would rescan the whole active set, which SPEC.md:11 forbids
    ("不得按全量预约反复扫描每项冲突"). Keeping one sorted list per resource makes each insert,
    removal and overlap probe O(log n + equal-start group) instead of O(total reservations).

    Entries are (start, end, id) so a probe can locate neighbours by start alone and then run
    the same half-open comparison the rest of the tool uses. Lists tolerate a repeated start,
    while removal matches the whole triple so it never drops a different reservation.
    """

    def __init__(self, rows):
        self.by_resource = {}
        for row in rows:
            self.by_resource.setdefault(row["resource"], []).append(
                (row["start"], row["end"], row["id"]))
        for entries in self.by_resource.values():
            entries.sort()

    def add(self, resource, start, end, ident):
        insort(self.by_resource.setdefault(resource, []), (start, end, ident))

    def remove(self, resource, start, end, ident):
        entries = self.by_resource[resource]
        entries.pop(bisect_left(entries, (start, end, ident)))
        if not entries:
            # Drop the empty bucket so a long run of reservations on distinct resources does not
            # leave thousands of empty lists behind for the final sweep.
            del self.by_resource[resource]

    def overlaps(self, resource, start, end):
        entries = self.by_resource.get(resource)
        if not entries:
            return False
        # The first entry whose start is >= start; every earlier entry starts below it, so only
        # that predecessor and the equal-start/successor group can possibly overlap [start, end).
        position = bisect_left(entries, (start,))
        if position and entries[position - 1][1] > start:
            return True
        for entry in entries[position:]:
            if entry[0] >= end:
                return False
            if entry[0] < end:
                return True
        return False


def run_apply(active, raw_events, raw_closed):
    """Validate then stage the whole batch; commit only if every event succeeds.

    SPEC.md:11 requires all-or-nothing: on any failure the caller emits empty active/results,
    so all mutation happens on these local copies and nothing escapes before the final return.
    """
    if not isinstance(raw_events, list) or not 1 <= len(raw_events) <= MAX_EVENTS:
        return failure("invalid-request")
    # Copy the records so a rejected batch cannot leave the caller's active list half-mutated.
    records = {ident: dict(row) for ident, row in active.items()}
    stage = IntervalIndex(records.values())
    problem = first_overlap(sorted(records.values(), key=sort_key))
    if problem:
        return failure(problem)
    # CHANGE-G2.md:3 — closed windows are checked once, before any event is looked at, so an
    # invalid-window always outranks every per-item error. The index is built after validation so
    # it never holds a half-checked window list.
    problem = window_problem(raw_closed)
    if problem:
        return failure(problem)
    closed = ClosedIndex(raw_closed)

    seen = {}
    results = []
    for index, raw in enumerate(raw_events):
        event, problem = read_event(raw)
        if problem:
            return failure(problem, index)
        # Identity is checked before business so a replay never re-tests reservation state
        # (SPEC.md:9); shape above already ran first, so ordering is shape, identity, business.
        mark = fingerprint(event)
        known = seen.get(event["event_id"])
        if known is not None:
            if known != mark:
                return failure("conflicting-event", index)
            results.append({"event_id": event["event_id"], "outcome": "replay"})
            continue
        seen[event["event_id"]] = mark
        ident = event["id"]
        current = records.get(ident)
        kind = event["kind"]
        if kind == "reserve":
            if current is not None:
                return failure("duplicate-reservation", index)
            if closed.intersects(event["resource"], event["start"], event["end"]):
                return failure("window-closed", index)
            if stage.overlaps(event["resource"], event["start"], event["end"]):
                return failure("overlap", index)
            row = {"id": ident, "resource": event["resource"], "owner": event["owner"],
                   "start": event["start"], "end": event["end"], "revision": 1}
            records[ident] = row
            stage.add(row["resource"], row["start"], row["end"], ident)
            results.append({"event_id": event["event_id"], "outcome": "applied"})
        elif kind == "release":
            # Release only drops the record, so closed windows cannot block it (CHANGE-G2.md:3)
            # and an existing reservation may still leave a closed resource.
            if current is None:
                return failure("unknown-reservation", index)
            del records[ident]
            stage.remove(current["resource"], current["start"], current["end"], ident)
            results.append({"event_id": event["event_id"], "outcome": "applied"})
        else:
            # CHANGE-G2.md:5,7 — existence first, then the revision guard, and only then the
            # target checks; a stale if_revision or a saturated revision must not be reported as
            # window-closed/overlap. The stored record is replaced in place with the same id.
            if current is None:
                return failure("unknown-reservation", index)
            from_revision = current["revision"]
            if event["if_revision"] != from_revision or from_revision >= MAX_VALUE:
                return failure("revision-conflict", index)
            # Removing the reservation before the probes is what excludes it from its own target
            # conflict check, so an in-place move that still overlaps only other records fails.
            stage.remove(current["resource"], current["start"], current["end"], ident)
            if closed.intersects(event["resource"], event["start"], event["end"]):
                return failure("window-closed", index)
            if stage.overlaps(event["resource"], event["start"], event["end"]):
                return failure("overlap", index)
            row = {"id": ident, "resource": event["resource"], "owner": event["owner"],
                   "start": event["start"], "end": event["end"],
                   "revision": from_revision + 1}
            records[ident] = row
            stage.add(row["resource"], row["start"], row["end"], ident)
            results.append({"event_id": event["event_id"], "outcome": "applied",
                            "fromRevision": from_revision, "toRevision": row["revision"]})

    return {"status": "ok", "active": sorted(records.values(), key=sort_key), "results": results}


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation == "apply":
        # SPEC.md:7 — active is validated first; then the closed windows (CHANGE-G2.md:3), and
        # only then are events inspected in input order. `closed` is accepted only for apply;
        # inspect below keeps its old key set, so a closed field there stays invalid-request.
        keys = request.keys()
        if not APPLY_FIELDS <= keys or keys - APPLY_FIELDS - APPLY_FIELDS_OPTIONAL:
            return failure("invalid-request")
        active, problem = read_active(request["active"])
        if problem:
            return failure(problem)
        return run_apply(active, request["events"], request.get("closed", []))
    if operation != "inspect" or request.keys() - {"operation", "active"}:
        return failure("invalid-request")
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}

