    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def read_event(raw):
    """Return (event, problem) for one raw event; shape only, never current reservation state.

    ledger applies the business rules (duplicate-reservation, unknown-reservation,
    revision-conflict) itself so that per-item ordering stays shape, then identity, then business
    as SPEC.md:9 and CHANGE-G2.md:7 require. This module therefore never reads reservations or
    closed windows; it only decides whether the item is well formed.
    """
    if not isinstance(raw, dict):
        return None, "invalid-event"
    kind = raw.get("kind")
    if kind == "reserve":
        if raw.keys() != RESERVE_FIELDS:
            return None, "invalid-event"
        if (not name(raw["id"]) or not name(raw["resource"]) or not name(raw["owner"])
                or not integer(raw["start"]) or not integer(raw["end"])
                or raw["start"] >= raw["end"]):
            return None, "invalid-event"
    elif kind == "release":
        if raw.keys() != RELEASE_FIELDS or not name(raw["id"]):
            return None, "invalid-event"
    elif kind == "transfer":
        # CHANGE-G2.md:5 — transfer repeats the reserve field rules and adds if_revision, which
        # obeys the old revision rule (whole number 1..1e9, booleans excluded). Revision values are
        # validated here, but whether if_revision matches the stored revision is ledger's call.
        if raw.keys() != TRANSFER_FIELDS:
            return None, "invalid-event"
        if (not name(raw["id"]) or not name(raw["resource"]) or not name(raw["owner"])
                or not integer(raw["start"]) or not integer(raw["end"])
                or raw["start"] >= raw["end"] or not integer(raw["if_revision"], 1)):
            return None, "invalid-event"
    else:
        return None, "invalid-event"
    if not name(raw["event_id"]):
        return None, "invalid-event"
    return raw, None


def fingerprint(event):
    """Content identity of a shape-valid event, independent of the object's field order.

    Sorting keys before serializing makes {kind.., id..} and {id.., kind..} compare equal, which
    SPEC.md:9 requires for replay detection. read_event has already restricted every value to a
    string or an int, so the sorted-key dump identifies content unambiguously. A transfer and a
    reserve can never collide because each kind has a distinct key set and a distinct kind value.
    """
    return json.dumps(event, sort_keys=True, separators=(",", ":"))

